def q(i,t,dom,stage,src,ev,qq,ans,mech,cond,stat='Review-Ready'):
 return {'question_id':i,'creation_batch':'batch_001','question':qq,'primary_type':t,'knowledge_domain':dom,'process_stage':stage,'source_ids':[src],'evidence_ids':[ev],'knowledge_unit_ids':['KU-'+i],'question_family_id':'F-'+i,'reference_answer':ans,'key_answer_points':[ans], 'necessary_mechanism':mech,'applicable_conditions':cond,'acceptable_alternatives':['同义且不扩大来源适用范围的表述。'],'common_misconceptions':['将特定核算方法、案例或实验条件推广为所有电解槽。'],'critical_errors':['把来源未支持的普适因果或定量效果写成结论。'],'candidate_status':'Candidate','evidence_status':'A-direct-fulltext' if src in ['P6-IPCC-2019','P6-ICSOBA-2025-AL16'] else 'C-abstract-only','expert_review_status':'Not-Reviewed','review_pool_status':stat,'item_version':'P6-batch001-candidate','model_assisted_generation':True}
Q=[
q('N601','K5','D14','异常/环境','P6-IPCC-2019','EV-N601','为什么不能把某一固定电压阈值当作所有电解槽识别全部PFC排放的充分条件？','不能。IPCC区分高、低压阳极效应，并指出PFC可在电压未越过阈值时产生；阈值识别的适用性取决于核算方法和设施定义。','LVAE可不表现为超过设定电压阈值。','限PFC核算与IPCC定义，不等同于任何异常诊断规则。'),
q('N602','K5','D14','异常/环境','P6-IPCC-2019','EV-N602','为何不能将一个槽型的阳极效应频率和持续时间记录直接用于另一槽型的斜率法PFC核算？','IPCC指出某些技术类别的频率和持续时间数据可能与其他技术不可比，并采用技术特异系数；直接迁移会引入核算偏差。','活动数据定义、控制技术和系数均可能随槽型变化。','限IPCC PFC清单核算。'),
q('N603','K1','D14','异常/环境','P6-IPCC-2019','EV-N603','IPCC将原铝生产PFC排放划分为哪几类来源？','在适用时，总PFC排放由高压阳极效应、低压阳极效应和电解槽启动期间的排放构成。','不同排放通道须分别识别和核算。','限IPCC 2019核算框架。'),
q('N604','E1','D14','异常/环境','P6-IPCC-2019','EV-N604','“未出现明显高电压阳极效应，就可以确认没有PFC排放”这一判断是否被IPCC框架支持？','不支持。低压阳极效应可产生PFC而未超过电压阈值；应说明测量和核算边界。','电压信号不是PFC排放的充分否定证据。','限IPCC所述LVAE/HVAE概念。'),
q('N605','K3','D14','异常/环境','P6-IPCC-2019','EV-N605','为何PFC排放核算除了阳极效应数据还需要明确铝产量和系数口径？','斜率法将AE分钟数据与产量及技术或设施特异系数关联；只报事件时间不能构成完整排放结果。','活动数据、产量与系数共同决定计算。','限相关IPCC方法。'),
q('N606','K5','D10','预热/启动','P6-ICSOBA-2025-AL16','EV-N606','为什么电解槽预热时间和最终温度不能脱离热损失与预热设备能量输入给出统一值？','EGA案例表明二者受槽热损失和预热输入共同决定；相同目标不能假定不同槽具有相同时间。','热损失与输入能量共同约束升温过程。','限该工业案例；具体参数需按槽型审核。'),
q('N607','K2','D10','预热/启动','P6-ICSOBA-2025-AL16','EV-N607','预热评价为什么除最终平均温度外还应关注温度分布和升温速率？','该案例将最终表面温度、分布、垂直温度梯度和升温速率并列为预热质量因素；单一平均值不能描述热均匀性。','热应力风险与空间/时间温度差有关。','限电解槽阴极预热的案例性评价框架。'),
q('N608','K5','D10','预热/启动','P6-ICSOBA-2025-AL16','EV-N608','为什么在槽温不足时加入液态电解质会提高早期失效风险？','案例说明低温加入约960°C液态电解质可能造成阴极热冲击和开裂，从而缩短寿命。','较大温差可产生热应力。','限文中材料、工况及预热阶段；不提供通用温度阈值。'),
q('N609','K4','D10','预热/启动','P6-ICSOBA-2025-AL16','EV-N609','若预热监测仅有低频人工读数，哪些信息缺口可能妨碍及时纠正异常？','可能缺少温度偏差、表面均匀性和趋势的及时信息；案例中的自动化高频采集旨在缩短发现与纠正延迟。','监测频率影响异常可观测性与处置时效。','限EGA案例，不断言所有自动系统都必然改善寿命。'),
q('N610','K6','D10','预热/启动','P6-ICSOBA-2025-AL16','EV-N610','只知道“某槽预热完成”，能否据此判断其可安全进入浴液加入阶段？','不能。还需至少知道温度水平、分布/梯度、升温过程及槽型程序要求；“完成”本身不是充分工程证据。','安全转换依赖多个预热质量指标。','限预热—启动决策的信息充分性判断。'),
q('N611','E1','D06','寿命/失效','P6-SINTEF-2017-CATHODE','EV-N611','一座停槽电解槽的拆槽尸检发现不均匀阴极磨损和坑洞，能否据此断定所有槽型的阴极寿命与失效机理？','不能。该研究是特定服役2461天、特定碳块内衬的拆槽观察；可支持该案例的形貌与分析方法，不足以确定所有槽型的通用寿命或唯一机理。','案例观察与跨槽型因果推广必须分开。','限SINTEF出版页摘要。','Candidate'),
q('N612','K2','D06','寿命/失效','P6-SINTEF-2017-CATHODE','EV-N612','为什么拆槽阴极磨损研究需要在不同位置取样并结合形貌和微结构分析？','该尸检研究在不同位置钻取样品并使用CT、光学和电子显微分析；多位置、多尺度观察有助于描述不均匀磨损及其相组成/微结构特征。','空间差异需要空间采样；形貌与微结构提供互补证据。','限该研究的分析设计，不推出唯一磨损机理。','Candidate'),
q('N613','E1','D05','异常/阳极效应','P6-SINTEF-2015-PAE','EV-N613','双阳极低氧化铝冰晶石熔体的实验结果能否直接证明工业大槽中任何低压阳极效应的空间分布？','不能。该研究是特定双阳极实验装置；它可提供部分阳极效应的实验线索，但工业槽的几何、电流分布和控制条件不同。','实验外推需检查尺度与边界条件。','限SINTEF出版页摘要。','Candidate'),
q('N614','K2','D05','异常/阳极效应','P6-SINTEF-2015-PAE','EV-N614','部分阳极效应实验中，两个阳极的电流承担为何可能不同？','该实验摘要报告阳极会随其反应阻力改变电流承担；这说明并联阳极在低氧化铝条件下可出现不完全相同的反应状态。','支路反应阻力差异可伴随电流分配差异。','限该实验装置和低氧化铝冰晶石熔体。','Candidate'),
q('N615','K5','D06','寿命/失效','P6-SINTEF-2017-CATHODE','EV-N615','发现阴极磨损不均匀时，为什么不能仅凭一个位置的样品代表整槽状态？','拆槽研究观察到整槽磨损不均匀并出现典型坑洞；单点结果可能遗漏空间差异，因此采样计划应与问题的空间分布相匹配。','非均匀现象要求避免单点外推。','限特定拆槽案例，不能给出统一取样数量。','Candidate')]
